package com.ryanjei.orushio.pve.economy;
import static org.junit.jupiter.api.Assertions.*;import com.ryanjei.orushio.pve.map.*;import com.ryanjei.orushio.pve.persistence.RepositoryException;import java.nio.file.*;import java.time.Duration;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
class YamlGameplaySettingsRepositoryTest{@TempDir Path temp;@Test void stableIdと全設定をAtomic保存して再読込する(){var repository=new YamlGameplaySettingsRepository(temp);GameplaySettings value=new GameplaySettings(List.of(new GameplaySettings.ResourceZone(UUID.randomUUID(),PointCategory.MINING,"IRON_ORE",4,Duration.ofSeconds(30),new Cuboid(0,0,0,2,2,2))),List.of(new GameplaySettings.Shop(UUID.randomUUID(),new BlockPoint(1,2,3,0,0),ShopType.WEAPON,"SWORD",List.of(new GameplaySettings.Product(0,PointCategory.MINING,5,new ItemSpec("WOODEN_SWORD",1,Map.of("minecraft:sharpness",1),true))))));repository.save("map-a",value);assertEquals(value,repository.load("map-a"));repository.save("map-a",value);assertTrue(Files.exists(temp.resolve("map-a/gameplay-settings.yml.bak")));}@Test void 未設定MapとschemaVersion1の空設定を読める()throws Exception{var repository=new YamlGameplaySettingsRepository(temp);assertEquals(GameplaySettings.empty(),repository.load("map-a"));write("schemaVersion: \"1\"\nresourceCount: \"0\"\nshopCount: \"0\"\n");assertEquals(GameplaySettings.empty(),repository.load("map-a"));}@Test void Shop型欠落をcategoryから推測せず拒否する()throws Exception{var repository=new YamlGameplaySettingsRepository(temp);UUID id=UUID.randomUUID();write("schemaVersion: \"1\"\nresourceCount: \"0\"\nshopCount: \"1\"\nshop.0.id: \""+id+"\"\nshop.0.location: \"1,2,3,0,0\"\nshop.0.category: \"WEAPON\"\nshop.0.productCount: \"0\"\n");assertThrows(RepositoryException.class,()->repository.load("map-a"));}@Test void 正常な件数があってもunknownSchemaだけを理由に拒否する()throws Exception{var repository=new YamlGameplaySettingsRepository(temp);write("schemaVersion: \"99\"\nresourceCount: \"0\"\nshopCount: \"0\"\n");assertThrows(RepositoryException.class,()->repository.load("map-a"));}@Test void schemaVersion欠落を拒否する()throws Exception{var repository=new YamlGameplaySettingsRepository(temp);write("resourceCount: \"0\"\nshopCount: \"0\"\n");assertThrows(RepositoryException.class,()->repository.load("map-a"));}@Test void ResourceMaterialは大文字enum形式だけを受理する()throws Exception{var repository=new YamlGameplaySettingsRepository(temp);GameplaySettings value=new GameplaySettings(List.of(new GameplaySettings.ResourceZone(UUID.randomUUID(),PointCategory.MINING,"STONE",1,Duration.ofSeconds(1),new Cuboid(0,0,0,1,1,1))),List.of());repository.save("map-a",value);assertEquals("STONE",repository.load("map-a").resourceZones().getFirst().material());String yaml=Files.readString(path()).replace("STONE","stone");Files.writeString(path(),yaml);assertThrows(RepositoryException.class,()->repository.load("map-a"));}private Path path(){return temp.resolve("map-a/gameplay-settings.yml");}private void write(String yaml)throws Exception{Files.createDirectories(path().getParent());Files.writeString(path(),yaml);}}
